#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    unsigned long long row[61] = {0};
    row[0] = 1ULL;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (j) putchar(' ');
            printf("%llu", row[j]);
        }
        putchar('\n');
        row[i + 1] = 1ULL;
        for (int j = i; j > 0; --j) {
            row[j] = row[j] + row[j - 1];
        }
        row[0] = 1ULL;
    }
    return 0;
}
